"""Frozen learned teacher; fitted probes; exact model-Y witness and model-X HRT."""
from pathlib import Path
import json,time,hashlib
import numpy as np
from scipy.special import expit,logit,logsumexp
from sklearn.datasets import load_digits
from sklearn.neural_network import MLPClassifier
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import train_test_split
from experiments import kl
R=Path(__file__).resolve().parents[1];SEED=31092026;REPS=50;NS=[2000,8000];FIT_SEEDS=[17,29,43];B=3.;EPS=.02;ALPHA=.05;HRT_DRAWS=99
cfg={'seed':SEED,'repetitions_per_fit':REPS,'audit_sizes':NS,'fit_seeds':FIT_SEEDS,'B':B,'epsilon':EPS,'alpha':ALPHA,'hrt_resamples':HRT_DRAWS,'teacher_hidden':[64,32],'probe_training_cases':4000,'effect':2.0,'covariate_noise':.03,'data':'sklearn digits; teacher target digit parity; continuous H generated by adding Gaussian noise to remaining real images','status':'Design fixed before first execution; exploratory study, not preregistered external validation'}
protocol=R/'results/representation_protocol.json'
if not protocol.exists():protocol.write_text(json.dumps(cfg|{'code_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()},indent=2))
def main():
 start=time.monotonic();ds=load_digits();xx=ds.data/16;yy=ds.target%2;train,pool=train_test_split(np.arange(len(yy)),train_size=1000,random_state=SEED,stratify=yy)
 teacher=MLPClassifier(hidden_layer_sizes=(64,32),activation='relu',alpha=.01,max_iter=400,random_state=SEED,early_stopping=True,n_iter_no_change=20).fit(xx[train],yy[train]);source=xx[pool]
 def features(h):
  a=np.maximum(0,np.einsum('ij,jk->ik',h,teacher.coefs_[0])+teacher.intercepts_[0]);return np.maximum(0,np.einsum('ij,jk->ik',a,teacher.coefs_[1])+teacher.intercepts_[1])
 def sample(rng,n,genuine):
  h=source[rng.integers(len(source),size=n)]+rng.normal(0,.03,(n,64));r=features(h);t=(np.einsum('ij,jk->ik',r,teacher.coefs_[2])+teacher.intercepts_[2]).ravel();t=np.clip(t,-4,4)
  z=rng.integers(0,2,n)*2-1;pp=EPS+(1-2*EPS)*expit(t+2*z) if genuine else EPS+(1-2*EPS)*expit(t)
  p0=.5*(EPS+(1-2*EPS)*expit(t+2)+EPS+(1-2*EPS)*expit(t-2)) if genuine else pp
  y=rng.random(n)<pp;g=np.c_[r,z] if genuine else r
  return h,g,y,p0,pp
 raw=[];fits=[]
 for seed in FIT_SEEDS:
  for genuine in [False,True]:
   rng=np.random.default_rng(SEED+seed+100*int(genuine));h,g,y,_,_=sample(rng,4000,genuine)
   q0=LogisticRegression(C=1.,max_iter=1000).fit(h,y);q1=LogisticRegression(C=1.,max_iter=1000).fit(g,y)
   fits.append({'seed':seed,'genuine':genuine,'q0_coef':q0.coef_.tolist(),'q0_intercept':q0.intercept_.tolist(),'q1_coef':q1.coef_.tolist(),'q1_intercept':q1.intercept_.tolist()})
   for n in NS:
    for rep in range(REPS):
     h,g,y,p0,p1=sample(rng,n,genuine);r=np.clip(q0.predict_proba(h)[:,1],EPS,1-EPS);z0=logit(r);target=q1.decision_function(g);q=expit(z0+np.clip(target-z0,-B,B));D=np.where(y,np.log(q/r),np.log((1-q)/(1-r)));w=kl(p0,r);T=D-w;L=np.log(1/EPS)
     eb=float(T.mean()-np.sqrt(2*T.var(ddof=1)*np.log(2/ALPHA)/n)-7*(2*B+L)*np.log(2/ALPHA)/(3*(n-1)))
     gainlower=float(D.mean()-np.sqrt(2*D.var(ddof=1)*np.log(2/ALPHA)/n)-7*2*B*np.log(2/ALPHA)/(3*(n-1)))
     ts=np.array([.01,.025,.05,.1,.25,.5,.9]);loge=float(logsumexp(np.log1p(ts[:,None]*T/(B+L)).sum(1))-np.log(len(ts)))
     if genuine:
      # Conditional on H, the learned representation is fixed and only Z is resampled.
      z=g[:,-1];base=target-q1.coef_[0,-1]*z;lp=[]
      for newz in [-1,1]:
       pred=expit(z0+np.clip(base+q1.coef_[0,-1]*newz-z0,-B,B));lp.append(np.where(y,np.log(pred),np.log1p(-pred)))
      sims=np.sum(lp[0]+rng.integers(0,2,(HRT_DRAWS,n))*(lp[1]-lp[0]),axis=1);observed=float(np.where(y,np.log(q),np.log1p(-q)).sum());pcrt=float((1+np.sum(sims>=observed))/(HRT_DRAWS+1))
     else:pcrt=1. # G is deterministically fixed by H: every exact conditional resample ties.
     # Conditional information integrand, averaged only as a descriptive Monte Carlo estimate.
     model_i=float(np.mean(kl(p1,p0)))
     raw.append({'fit_seed':seed,'genuine':genuine,'n':n,'rep':rep,'gain':float(D.mean()),'witness':float(w.mean()),'gain_lower':gainlower,'eb_lower':eb,'betting_log_e':loge,'hrt_p':pcrt,'information_integrand_mean':model_i})
    print('Completed',seed,genuine,n,flush=True)
 rows=[]
 for genuine in [False,True]:
  for n in NS:
   rr=[x for x in raw if x['genuine']==genuine and x['n']==n];rows.append({'genuine':genuine,'n':n,'repetitions':len(rr),'mean_gain':float(np.mean([x['gain'] for x in rr])),'mean_witness':float(np.mean([x['witness'] for x in rr])),'mean_eb_lower':float(np.mean([x['eb_lower'] for x in rr])),'predictive_positive':float(np.mean([x['gain_lower']>0 for x in rr])),'eb_positive':float(np.mean([x['eb_lower']>0 for x in rr])),'betting_positive':float(np.mean([x['betting_log_e']>=np.log(1/ALPHA) for x in rr])),'hrt_rejection':float(np.mean([x['hrt_p']<=ALPHA for x in rr])),'mean_information_integrand':float(np.mean([x['information_integrand_mean'] for x in rr]))})
 out={'config':cfg,'rows':rows,'teacher_train_accuracy':float(teacher.score(xx[train],yy[train])),'teacher_pool_accuracy':float(teacher.score(xx[pool],yy[pool])),'teacher_training_indices':train.tolist(),'pool_indices':pool.tolist(),'elapsed_seconds':time.monotonic()-start,'scope':'Semisynthetic labels from a learned teacher; continuous 64-dimensional inputs; both probes fitted on independent generated training data. Repetitions share a teacher and fitted probes within each seed. HRT p-values test independence; information bounds quantify information under the teacher distribution.'}
 (R/'results/representation_audit.json').write_text(json.dumps(out,indent=2));(R/'results/representation_trials.json').write_text(json.dumps(raw));(R/'results/representation_fitted_probes.json').write_text(json.dumps(fits));np.savez_compressed(R/'results/representation_teacher.npz',**{f'W{i}':w for i,w in enumerate(teacher.coefs_)},**{f'b{i}':b for i,b in enumerate(teacher.intercepts_)})
 print(json.dumps(out['rows'],indent=2),flush=True)
if __name__=='__main__':main()
